open('alt_photo_rework.py', 'w').write('"""Alternative photo after the SECOND rejection of the same scene (point 3, Michele 2026-11-12).\nPure planning + the photo swap on disk; every outside call is injected (pick / fetch / evaluate), so it is testable with fakes.\nWhen it applies: a scene was rejected by the clip QC with its own photo, was reworked once automatically (job[\'auto_reworked\']),\nand the reworked clip is rejected again. Instead of parking the job, the best OTHER photo of the same room (listing_scraper.pick_alternative_photo,\nthe shared selection step) replaces the scene\'s photo and the scene goes through the ONE rework runner (_run_redo) once more, with the same clip QC.\nAccepted (no reject, no flag) -> the job goes on by itself. Rejected or flagged again -> the job parks for the operator, as before.\nNever tried: switch off, any flagged scene in the stop, scene not rejected twice, alternative already tried for the scene (ONE per scene),\nno other photo, photo not downloadable, rework budget used up. Nothing is ever deleted: the replaced files are MOVED to <job>/rejected_photos/."""\nimport os\nimport re\nimport shutil\nfrom datetime import datetime\nfrom pathlib import Path\n\nIMAGE_EXTS = (".jpg", ".jpeg", ".png", ".webp")\n\n\ndef enabled():\n    return os.getenv("PVS_AUTO_ALT_PHOTO", "0").strip().lower() in ("1", "true", "yes", "on")\n\n\ndef _park(job, reason):\n    return {"scene_ids": [], "reason": reason}\n\n\ndef _unique(path: Path) -> Path:\n    if not path.exists():\n        return path\n    n = 2\n    while True:\n        cand = path.with_name(f"{path.stem}_{n}{path.suffix}")\n        if not cand.exists():\n            return cand\n        n += 1\n\n\ndef _park_files(job_dir: Path, sid: str):\n    """Moves the scene\'s current photo and every file derived from it (enhanced / dewatermarked) out of the way, and copies its current clip.\n    The old clip is only copied: the regeneration overwrites clips/<sid>.mp4 as in any rework. Returns the list of names parked."""\n    rej = job_dir / "rejected_photos"\n    rej.mkdir(exist_ok=True)\n    parked = []\n    img_dir = job_dir / "images"\n    for ext in IMAGE_EXTS:\n        f = img_dir / f"{sid}{ext}"\n        if f.exists():\n            t = _unique(rej / f"{sid}__old{ext}")\n            shutil.move(str(f), str(t))\n            parked.append(t.name)\n    enh = job_dir / "enhanced"\n    pat = re.compile("^" + re.escape(sid) + r"(_dewm)?_L\\dU\\d_enhanced\\.jpg$|^" + re.escape(sid) + r"_dewatermarked\\.jpg$")\n    if enh.is_dir():\n        for f in sorted(enh.iterdir()):\n            if pat.match(f.name):\n                t = _unique(rej / f"{sid}__old_{f.name}")\n                shutil.move(str(f), str(t))\n                parked.append(t.name)\n    clip = job_dir / "clips" / f"{sid}.mp4"\n    if clip.exists():\n        t = _unique(rej / f"{sid}__old.mp4")\n        shutil.copy2(str(clip), str(t))\n        parked.append(t.name)\n    return parked\n\n\ndef prepare(job, job_dir, rejected, flagged, deps):\n    """-> {"scene_ids": [...], "reason": str}. Empty scene_ids = do not try (the caller parks the job as before).\n    deps: pick(selection_report, category, exclude_urls)->{"photo": {...}|None, "reason": str}; fetch(url)->bytes|None; evaluate(job, scene_ids)->{"allowed", "reasons"}."""\n    if not enabled():\n        return _park(job, "switch off")\n    if not rejected:\n        return _park(job, "no reject")\n    if flagged:\n        return _park(job, "flagged scenes need the operator")\n    cfg = job.get("scenes_config") or []\n    auto = set(job.get("auto_reworked") or [])\n    tried = job.setdefault("alt_photo", {})\n    plan = []\n    for i in rejected:\n        sc = cfg[i] if isinstance(i, int) and 0 <= i < len(cfg) else None\n        sid = (sc or {}).get("scene_id")\n        if not sid:\n            return _park(job, f"scene {i}: no scene_id")\n        if sid not in auto:\n            return _park(job, f"scene {sid}: not rejected twice yet")\n        if sid in tried:\n            return _park(job, f"scene {sid}: alternative photo already tried")\n        if not (sc or {}).get("category"):\n            return _park(job, f"scene {sid}: no category")\n        plan.append((sid, sc["category"]))\n    ids = [sid for sid, _ in plan]\n    ev = deps.evaluate(job, ids)\n    if not ev.get("allowed"):\n        return _park(job, "rework budget: " + "; ".join(ev.get("reasons") or []))\n    exclude = [e.get("new_url") for e in tried.values() if e.get("new_url")]\n    chosen = []\n    for sid, cat in plan:\n        out = deps.pick(job.get("selection_report") or {}, cat, exclude)\n        photo = (out or {}).get("photo")\n        if not photo:\n            tried[sid] = {"status": "none", "category": cat, "reason": (out or {}).get("reason"), "at": datetime.utcnow().isoformat()}\n            return _park(job, f"scene {sid}: {(out or {}).get(\'reason\')}")\n        data = deps.fetch(photo["url"])\n        if not data:\n            tried[sid] = {"status": "none", "category": cat, "reason": "photo not downloadable", "new_url": photo["url"], "at": datetime.utcnow().isoformat()}\n            return _park(job, f"scene {sid}: alternative photo not downloadable")\n        exclude.append(photo["url"])\n        chosen.append((sid, cat, photo, data))\n    job_dir = Path(job_dir)\n    (job_dir / "images").mkdir(exist_ok=True)\n    for sid, cat, photo, data in chosen:\n        parked = _park_files(job_dir, sid)\n        (job_dir / "images" / f"{sid}.jpg").write_bytes(data)\n        tried[sid] = {"status": "generating", "category": cat, "new_url": photo["url"], "rank_status": photo.get("rank_status"),\n                      "feature_visible": photo.get("feature_visible"), "quality": photo.get("quality"), "parked": parked,\n                      "at": datetime.utcnow().isoformat()}\n    return {"scene_ids": ids, "reason": "alternative photo"}\n\n\ndef record_outcome(job, redone_ids, failed_ids, rejected, flagged):\n    """After the QC of the clips made with an alternative photo: accepted / rejected_again / failed. Returns {scene_id: status} for the ones changed."""\n    cfg = job.get("scenes_config") or []\n    bad = {(cfg[i] or {}).get("scene_id") for i in list(rejected or []) + list(flagged or []) if isinstance(i, int) and 0 <= i < len(cfg)}\n    changed = {}\n    for sid, e in (job.get("alt_photo") or {}).items():\n        if e.get("status") != "generating":\n            continue\n        if sid in (failed_ids or []):\n            e["status"] = "failed"\n        elif sid in (redone_ids or []):\n            e["status"] = "rejected_again" if sid in bad else "accepted"\n        else:\n            continue\n        e["decided_at"] = datetime.utcnow().isoformat()\n        changed[sid] = e["status"]\n    return changed\n')
open('test_alt_photo_rework.py', 'w').write('"""Point 3 simulation (2026-11-12): alternative photo after the SECOND rejection of the same scene. Fakes only: no network, no Claude, no Luma.\nRun: python3 test_alt_photo_rework.py"""\nimport os, sys, tempfile, types\nfrom pathlib import Path\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport alt_photo_rework as apr\n\nres = []\ndef check(name, ok, info=""):\n    res.append(bool(ok)); print(("PASS " if ok else "FAIL ") + name + ("" if ok else "  -> " + str(info)))\n\ndef make_job(tmp, auto=("sc_bath",), cats=("living", "kitchen", "bathrooms")):\n    d = Path(tmp); (d / "images").mkdir(parents=True, exist_ok=True); (d / "enhanced").mkdir(exist_ok=True); (d / "clips").mkdir(exist_ok=True)\n    sids = ["sc_live", "sc_kit", "sc_bath"][:len(cats)]\n    for s in sids:\n        (d / "images" / f"{s}.jpg").write_bytes(b"OLD-" + s.encode())\n        (d / "enhanced" / f"{s}_L1U1_enhanced.jpg").write_bytes(b"ENH-" + s.encode())\n        (d / "clips" / f"{s}.mp4").write_bytes(b"CLIP-" + s.encode())\n    job = {"scenes_config": [{"scene_id": s, "category": c} for s, c in zip(sids, cats)], "auto_reworked": list(auto),\n           "selection_report": {"selected": {}, "candidate_urls": {}}, "rework_counts": {"sc_bath": 1}}\n    return job, d\n\ndef deps(photo=None, reason="ok", data=b"NEW", allowed=True, calls=None):\n    def pick(rep, cat, excl):\n        if calls is not None: calls.append((cat, list(excl)))\n        return {"photo": photo, "reason": reason}\n    return types.SimpleNamespace(pick=pick, fetch=lambda u: data, evaluate=lambda j, ids: {"allowed": allowed, "reasons": [] if allowed else ["cap"]})\n\nos.environ["PVS_AUTO_ALT_PHOTO"] = "1"\nP = {"url": "https://x/p7.jpg", "rank_status": "ranked", "feature_visible": True, "quality": "ok"}\n\nwith tempfile.TemporaryDirectory() as t:\n    job, d = make_job(t)\n    out = apr.prepare(job, d, [2], [], deps(P))\n    check("S1 twice-rejected scene -> alternative chosen, the scene id is returned for the rework runner", out["scene_ids"] == ["sc_bath"], out)\n    check("S2 the new photo is the scene\'s source image (images/<sid>.jpg)", (d / "images" / "sc_bath.jpg").read_bytes() == b"NEW")\n    rej = d / "rejected_photos"\n    check("S3 nothing is deleted: old photo, enhanced file and a copy of the clip are in rejected_photos/", len(list(rej.iterdir())) == 3 and (rej / "sc_bath__old.jpg").read_bytes() == b"OLD-sc_bath", sorted(x.name for x in rej.iterdir()))\n    check("S4 the old enhanced file is gone from enhanced/ (it would be reused by the rework), the other scenes untouched", not (d / "enhanced" / "sc_bath_L1U1_enhanced.jpg").exists() and (d / "enhanced" / "sc_kit_L1U1_enhanced.jpg").exists() and (d / "images" / "sc_kit.jpg").read_bytes() == b"OLD-sc_kit")\n    check("S5 the attempt is recorded in the job (status generating, new url, checks)", job["alt_photo"]["sc_bath"]["status"] == "generating" and job["alt_photo"]["sc_bath"]["new_url"] == P["url"] and job["alt_photo"]["sc_bath"]["feature_visible"] is True, job.get("alt_photo"))\n    # outcome: the clip with the alternative photo passes the QC\n    ch = apr.record_outcome(job, ["sc_bath"], [], [], [])\n    check("S6 alternative clip passes the QC -> accepted (the job goes on by itself)", ch == {"sc_bath": "accepted"} and job["alt_photo"]["sc_bath"]["status"] == "accepted", ch)\n    out2 = apr.prepare(job, d, [2], [], deps(P))\n    check("S7 ONE alternative per scene: a later reject of the same scene is not tried again", out2["scene_ids"] == [] and "already tried" in out2["reason"], out2)\n\nwith tempfile.TemporaryDirectory() as t:\n    job, d = make_job(t); apr.prepare(job, d, [2], [], deps(P))\n    ch = apr.record_outcome(job, ["sc_bath"], [], [2], [])\n    check("S8 alternative clip rejected again -> rejected_again (the job parks for the operator)", ch == {"sc_bath": "rejected_again"}, ch)\nwith tempfile.TemporaryDirectory() as t:\n    job, d = make_job(t); apr.prepare(job, d, [2], [], deps(P))\n    ch = apr.record_outcome(job, ["sc_bath"], [], [], [2])\n    check("S9 alternative clip flagged -> rejected_again (flags always go to the operator)", ch == {"sc_bath": "rejected_again"}, ch)\nwith tempfile.TemporaryDirectory() as t:\n    job, d = make_job(t); apr.prepare(job, d, [2], [], deps(P))\n    ch = apr.record_outcome(job, [], ["sc_bath"], [], [])\n    check("S10 alternative clip not generated -> failed", ch == {"sc_bath": "failed"}, ch)\n\ndef parked(label, job_kw=None, rejected=[2], flagged=[], dps=None, env=None, expect=""):\n    with tempfile.TemporaryDirectory() as t:\n        job, d = make_job(t, **(job_kw or {}))\n        old = os.environ.get("PVS_AUTO_ALT_PHOTO")\n        if env is not None: os.environ["PVS_AUTO_ALT_PHOTO"] = env\n        try: out = apr.prepare(job, d, rejected, flagged, dps or deps(P))\n        finally: os.environ["PVS_AUTO_ALT_PHOTO"] = old\n        untouched = (d / "images" / "sc_bath.jpg").read_bytes() == b"OLD-sc_bath" and not (d / "rejected_photos").exists()\n        check(label, out["scene_ids"] == [] and expect in out["reason"] and untouched, (out, untouched))\n        return job\n\nparked("S11 no alternative photo of this room (single-photo kitchen case) -> park, reason kept, files untouched", dps=deps(None, "no other photo of this room"), expect="no other photo")\nj = parked("S12 alternative photo cannot be downloaded (expired partner URL) -> park", dps=deps(P, data=None), expect="not downloadable")\ncheck("S13 the reason is recorded in the job for the operator", j["alt_photo"]["sc_bath"]["status"] == "none" and "downloadable" in j["alt_photo"]["sc_bath"]["reason"], j.get("alt_photo"))\nparked("S14 rework budget used up -> park", dps=deps(P, allowed=False), expect="budget")\nparked("S15 a flagged scene in the same stop -> the operator decides everything", flagged=[0], expect="flagged")\nparked("S16 scene rejected only once (not in auto_reworked) -> not tried", job_kw={"auto": ()}, expect="not rejected twice")\nparked("S17 switch off (default) -> nothing", env="0", expect="switch off")\nparked("S18 no reject -> nothing", rejected=[], expect="no reject")\nparked("S19 reject index outside the scenes -> park", rejected=[9], expect="no scene_id")\ncalls = []\nwith tempfile.TemporaryDirectory() as t:\n    job, d = make_job(t, auto=("sc_kit", "sc_bath"))\n    out = apr.prepare(job, d, [1, 2], [], deps(P, calls=calls))\n    check("S20 two scenes rejected twice -> both get an alternative, the second pick excludes the first url (never the same photo twice)", out["scene_ids"] == ["sc_kit", "sc_bath"] and calls[1][1] == [P["url"]], (out, calls))\nwith tempfile.TemporaryDirectory() as t:\n    job, d = make_job(t, auto=("sc_kit", "sc_bath"))\n    n = {"i": 0}\n    def pick2(rep, cat, excl):\n        n["i"] += 1\n        return {"photo": P if n["i"] == 1 else None, "reason": "no other photo of this room"}\n    dps = types.SimpleNamespace(pick=pick2, fetch=lambda u: b"NEW", evaluate=lambda j, ids: {"allowed": True, "reasons": []})\n    out = apr.prepare(job, d, [1, 2], [], dps)\n    check("S21 all or nothing: one scene has no alternative -> no file moved, the job parks as before", out["scene_ids"] == [] and (d / "images" / "sc_kit.jpg").read_bytes() == b"OLD-sc_kit" and not (d / "rejected_photos").exists(), out)\n\n# wiring (source checks, same style as test_rework_qc.py)\nsrc = Path("api_server.py").read_text()\ni = src.index("async def _run_redo(")\nbody = src[i:src.index("async def run_redo_scene(")]\ng = src[src.index("async def _rework_qc_gate("):i]\ncheck("S22 the gate records the outcome and tries the alternative BEFORE it parks; an exception there never blocks (falls back to parking)",\n      g.index("record_outcome(") < g.index("_apr.prepare") < g.index(\'"status": "awaiting_approval"\') and "non-fatal, the job parks as before" in g)\ncheck("S23 only a pure-reject stop is tried (no flagged scene) and only with the switch on", \'qc["rejected"] and not qc["flagged"] and _apr.enabled()\' in g)\ncheck("S24 the runner repeats ITSELF (one runner, no second path) and returns; \'alt\' is handled before the parking branch",\n      body.index(\'gate == "alt"\') < body.index("if gate:") and \'label="Rework foto alternativa"\' in body and body.count("run_reassemble_only(job_id)") == 1)\ncheck("S25 the alternative photo comes from the shared selection step and the one download function", "_ls.pick_alternative_photo" in src and "_ls.fetch_photo_bytes(url, timeout=20)" in src)\nprint("%d/%d PASS" % (sum(res), len(res)))\nsys.exit(0 if all(res) else 1)\n')
open('test_alt_photo_runner.py', 'w').write('"""Point 3, the REAL runner (api_server._run_redo + _rework_qc_gate + alt_photo_rework) driven with fakes at the edges: no Luma, no Claude, no network.\nNeeds the server environment (fastapi): where it is not installed the test says SKIPPED. Run: python3 test_alt_photo_runner.py"""\nimport asyncio, os, sys, tempfile, types\nfrom pathlib import Path\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\ntry:\n    import fastapi  # noqa\nexcept Exception:\n    print("SKIPPED (fastapi not installed here: run it on the server)"); sys.exit(0)\nfor name in ("fal_client", "moviepy"):\n    if name not in sys.modules:\n        try: __import__(name)\n        except Exception: sys.modules[name] = types.ModuleType(name)\nTMP = Path(tempfile.mkdtemp())\nos.environ["PVS_JOBS_DIR"] = str(TMP)\nos.environ["PVS_AUTO_ALT_PHOTO"] = "1"\nimport api_server as A\nimport listing_scraper as LS\nA.JOBS_DIR = TMP\n\nres = []\ndef check(name, ok, info=""):\n    res.append(bool(ok)); print(("PASS " if ok else "FAIL ") + name + ("" if ok else "  -> " + str(info)))\n\nPHOTO = {"url": "https://x/alt.jpg", "rank_status": "ranked", "feature_visible": True, "quality": "ok"}\n\ndef run(qc_seq, pick=PHOTO, auto=("sc_bath",), jid="j1", switch="1"):\n    os.environ["PVS_AUTO_ALT_PHOTO"] = switch\n    d = TMP / jid\n    for sub in ("images", "enhanced", "clips"): (d / sub).mkdir(parents=True, exist_ok=True)\n    (d / "images" / "sc_bath.jpg").write_bytes(b"OLD"); (d / "clips" / "sc_bath.mp4").write_bytes(b"CLIP")\n    job = {"status": "running", "model_tier": "premium", "enable_vision_qc": True, "auto_reworked": list(auto), "property_name": "T",\n           "scenes_config": [{"scene_id": "sc_kit", "category": "kitchen"}, {"scene_id": "sc_live", "category": "living"}, {"scene_id": "sc_bath", "category": "bathrooms"}],\n           "scenes": [], "qc_results": [], "selection_report": {"selected": {}, "candidate_urls": {"bathrooms": ["u1", "u2"]}}}\n    A.JOBS[jid] = job\n    log = {"redo": [], "reasm": 0, "qc": 0}\n    async def fake_redo(j, jd, ids, deps, **kw):\n        log["redo"].append((list(ids), kw.get("label"), (Path(jd) / "images" / "sc_bath.jpg").read_bytes()))\n        return {"redone": [{"scene_id": s} for s in ids], "failed": [], "skipped": []}\n    def fake_qc(j, jd, redone, deps):\n        v = qc_seq[min(log["qc"], len(qc_seq) - 1)]; log["qc"] += 1\n        return {"rejected": [2] if v == "reject" else [], "flagged": [2] if v == "flag" else [], "checked": ["sc_bath"], "unchecked": []}\n    async def fake_reasm(job_id): log["reasm"] += 1\n    async def noop(*a, **k): return None\n    A._sr.redo_scenes = fake_redo; A._sr.qc_redone = fake_qc; A._sr.record_rework_cost = lambda *a, **k: None; A._sr.lost_generations = lambda *a, **k: []\n    A.run_reassemble_only = fake_reasm; A._notify_operator = noop; A._warm_previews = lambda *a, **k: None\n    A._redo_deps = lambda job_id: types.SimpleNamespace(log=types.SimpleNamespace(warning=lambda *a: None, info=lambda *a: None))\n    import vision_analysis as VA; VA.analyse_output = lambda *a, **k: {}\n    LS.pick_alternative_photo = lambda rep, cat, excl: {"photo": pick, "reason": "no other photo of this room" if not pick else "ok"}\n    LS.fetch_photo_bytes = lambda url, *a, **k: {"ok": True, "content": b"NEWPHOTO"}\n    A._rwp.count(job, ["sc_bath"])      # the automatic rework (first redo) already counted once, as in the pipeline\n    asyncio.run(A._run_redo(jid, ["sc_bath"], video=True, strict=False, policy=True, label="Rework automatico"))\n    return job, log\n\njob, log = run(["reject", "pass"])\ncheck("R1 rejected twice -> alternative photo -> passes: the SAME runner ran twice, the second time on the NEW photo, then ONE reassembly",\n      len(log["redo"]) == 2 and log["redo"][0][2] == b"OLD" and log["redo"][1][2] == b"NEWPHOTO" and log["redo"][1][1] == "Rework foto alternativa" and log["reasm"] == 1, log)\ncheck("R2 the job is not parked, the attempt says accepted, the rework budget counted both rounds", job["status"] != "awaiting_approval" and job["alt_photo"]["sc_bath"]["status"] == "accepted" and job["rework_counts"]["sc_bath"] == 2 and "alt_pending" not in job, (job["status"], job.get("alt_photo"), job.get("rework_counts")))\njob, log = run(["reject", "reject"], jid="j2")\ncheck("R3 alternative rejected too -> the job parks for the operator, no reassembly, only ONE alternative tried", len(log["redo"]) == 2 and log["reasm"] == 0 and job["status"] == "awaiting_approval" and job["alt_photo"]["sc_bath"]["status"] == "rejected_again", (log, job["status"], job.get("alt_photo")))\njob, log = run(["reject", "flag"], jid="j3")\ncheck("R4 alternative flagged -> parks for the operator", job["status"] == "awaiting_approval" and log["reasm"] == 0, job["status"])\njob, log = run(["reject"], pick=None, jid="j4")\ncheck("R5 no alternative photo -> parks at once, ONE redo only, the reason is in the job", len(log["redo"]) == 1 and job["status"] == "awaiting_approval" and job["alt_photo"]["sc_bath"]["status"] == "none", (log, job.get("alt_photo")))\njob, log = run(["reject"], switch="0", jid="j5")\ncheck("R6 switch off -> exactly today\'s behaviour (parks, one redo, no alt_photo in the job)", len(log["redo"]) == 1 and job["status"] == "awaiting_approval" and "alt_photo" not in job, (log, job.get("alt_photo")))\njob, log = run(["reject"], auto=(), jid="j6")\ncheck("R7 scene rejected only once (no automatic rework before) -> not tried", len(log["redo"]) == 1 and job["status"] == "awaiting_approval" and "alt_photo" not in job or job.get("alt_photo") == {}, (log, job.get("alt_photo")))\njob, log = run(["pass"], jid="j7")\ncheck("R8 first rework passes -> plain reassembly, no alternative involved", len(log["redo"]) == 1 and log["reasm"] == 1 and not job.get("alt_photo"), (log, job.get("alt_photo")))\nprint("%d/%d PASS" % (sum(res), len(res)))\nsys.exit(0 if all(res) else 1)\n')
print('ok')
